/* ── Unit 02 Problem Bank — Classification of Matter
   179 problems total (86 original + 60 added + 30 hard expansion + 3 easy multi-step)
   Difficulty: 68 easy | 61 medium | 50 hard
   Served via netlify/functions/get-premium-problem-set.js
   NOT imported by any public-facing page.
─────────────────────────────────────────────────────── */

export const ALL_PROBLEMS = [

/* ══════════════ CONCEPT — Classification (17) ══════════════ */
{id:'p01',difficulty:'easy',type:'concept',tag:'Concept', q:'Which of the following is a pure substance?', choices:['Salt water','Air','Distilled water (H2O)','Granite'], correct:2, solution:'Distilled water is a pure substance — it has a fixed composition (H2O) and definite properties. Salt water, air, and granite are all mixtures.'},
  {id:'p02',difficulty:'easy',type:'concept',tag:'Concept', q:'An element is best defined as:', choices:['Any substance that cannot be dissolved','A pure substance made of only one kind of atom','A mixture of two or more metals','A substance that cannot be heated'], correct:1, solution:'<p>An element contains only one type of atom. Every sample of that element is built from the same kind of atom, such as O, Fe, or C.</p><p>It also cannot be broken down into simpler substances by ordinary chemical changes.</p>'},
{id:'p03',difficulty:'easy',type:'concept',tag:'Concept', q:'Which of the following is a compound?', choices:['Carbon (C)','Oxygen gas (O2)','Water (H2O)','Nitrogen gas (N2)'], correct:2, solution:'A compound contains two or more different elements chemically bonded in a fixed ratio. Water (H2O) has hydrogen and oxygen bonded together. O2 and N2 are elements; carbon is an element.'},
{id:'p04',difficulty:'easy',type:'concept',tag:'Concept', q:'Salt water is best classified as:', choices:['An element','A compound','A homogeneous mixture','A heterogeneous mixture'], correct:2, solution:'Salt water is a homogeneous mixture (solution) — the dissolved salt is uniformly distributed throughout the water at the molecular level. You cannot see separate components.'},
{id:'p05',difficulty:'easy',type:'concept',tag:'Concept', q:'A bowl of mixed nuts is best classified as:', choices:['A compound','A homogeneous mixture','A heterogeneous mixture','An element'], correct:2, solution:'A heterogeneous mixture has a non-uniform composition — you can see and physically separate the different components (peanuts, almonds, cashews). Each region of the sample looks different.'},
{id:'p06',difficulty:'easy',type:'concept',tag:'Concept', q:'Which separation method is best for separating sand from water?', choices:['Distillation','Filtration','Evaporation','Chromatography'], correct:1, solution:'Filtration physically separates an insoluble solid (sand) from a liquid (water) using a filter. The sand stays on the filter; the water passes through.'},
{id:'p07',difficulty:'easy',type:'concept',tag:'Concept', q:'Which separation method is best for separating salt from water?', choices:['Filtration','Distillation or evaporation','Chromatography','Magnetism'], correct:1, solution:'Salt is dissolved in water — filtration will not work. Evaporation removes the water, leaving the salt behind. Distillation collects the pure water vapor, leaving the salt in the flask.'},
{id:'p08',difficulty:'medium',type:'concept',tag:'Concept', q:'A particle diagram shows pairs of the same atom bonded together, all identical. This substance is:', choices:['A compound','A heterogeneous mixture','An element in molecular form','A solution'], correct:2, solution:'Diatomic elements like O2, N2, and H2 are elements in molecular form — each molecule contains only one type of atom, so the substance is still an element, not a compound.'},
{id:'p09',difficulty:'medium',type:'concept',tag:'Concept', q:'A particle diagram shows two types of atoms bonded in a fixed 1:2 ratio throughout. This is:', choices:['A heterogeneous mixture','A homogeneous mixture','A compound','An element'], correct:2, solution:'A fixed ratio of two different atom types bonded together = a compound. The key word is "bonded" — compounds have chemical bonds between different elements, not just physical mixing.'},
{id:'p10',difficulty:'medium',type:'concept',tag:'Concept', q:'A particle diagram shows two different molecules mixed together, not bonded. This is:', choices:['A compound','An element','A pure substance','A mixture'], correct:3, solution:'When two different types of molecules are present but not bonded to each other, the substance is a mixture. If they are uniformly mixed, it is homogeneous; if clustered separately, it is heterogeneous.'},
{id:'p11',difficulty:'easy',type:'concept',tag:'Concept', q:'Which of the following is a heterogeneous mixture?', choices:['Sugar water','Vinegar','Blood','Table salt (NaCl)'], correct:2, solution:'Blood is a heterogeneous mixture — it contains red blood cells, white blood cells, platelets, and plasma that are not uniformly distributed at the microscopic level. Sugar water and vinegar are solutions (homogeneous); NaCl is a pure compound.'},
  {id:'p12',difficulty:'easy',type:'concept',tag:'Concept', q:'What distinguishes a compound from a mixture?', choices:['Compounds contain only one element; mixtures contain two or more','Compounds are formed by chemical bonding in fixed ratios; mixtures are physically combined and variable','Compounds are always solid; mixtures are always liquid','Compounds can be separated by filtration; mixtures cannot'], correct:1, solution:'<p>A compound is made when elements are chemically bonded in a fixed ratio. That fixed composition is part of the substance\'s identity.</p><p>A mixture is only a physical combination, so the proportions can vary and the parts can usually be separated by physical methods such as filtration, evaporation, or distillation.</p>'},
{id:'p13',difficulty:'medium',type:'concept',tag:'Concept', q:'Which of the following is an example of a homogeneous mixture?', choices:['Oil and water','Sand and gravel','Bronze (copper-tin alloy)','Salad'], correct:2, solution:'Bronze is an alloy — a homogeneous mixture of metals where the composition is uniform throughout. Oil and water separate into layers (heterogeneous). Sand and gravel and salad are visibly non-uniform (heterogeneous).'},
{id:'p14',difficulty:'easy',type:'concept',tag:'Concept', q:'A student mixes iron filings and sand. The best method to separate them is:', choices:['Distillation','Filtration','A magnet','Evaporation'], correct:2, solution:'Iron is magnetic; sand is not. A magnet will attract and remove all iron filings from the sand, physically separating the two components of this heterogeneous mixture.'},
{id:'p15',difficulty:'medium',type:'concept',tag:'Concept', q:'Paper chromatography separates components of a mixture based on:', choices:['Differences in density','Differences in boiling point','Differences in particle size','Differences in how strongly each component is attracted to the paper and solvent'], correct:3, solution:'Chromatography separates based on differential affinity — components that stick more strongly to the stationary phase (paper) move slowly; those that favor the mobile phase (solvent) travel farther. Each component has a unique Rf value.'},
{id:'p16',difficulty:'easy',type:'concept',tag:'Concept', q:'Which of the following is NOT a pure substance?', choices:['Copper (Cu)','Carbon dioxide (CO2)','Oxygen gas (O2)','Chicken broth'], correct:3, solution:'Chicken broth is a mixture — it contains water, proteins, fats, salts, and other compounds that vary in proportion and can be physically separated. The others are pure substances with fixed, definite compositions.'},
{id:'p17',difficulty:'easy',type:'concept',tag:'Concept', q:'The chemical formula NaCl tells us that sodium chloride:', choices:['Is a mixture of Na and Cl atoms in any ratio','Is an element with two isotopes','Is a compound with Na and Cl bonded in a 1:1 ratio','Is a diatomic molecule of sodium'], correct:2, solution:'A chemical formula shows the exact ratio of atoms in a compound. NaCl has one sodium atom for every one chloride atom, chemically bonded together. This fixed ratio is what makes it a compound, not a mixture.'},

/* ══════════════ CONCEPT — Properties & Changes (19) ══════════════ */
  {id:'p18',difficulty:'easy',type:'concept',tag:'Concept', q:'Which of the following is a physical property?', choices:['Flammability','Ability to rust','Reactivity with acid','Density'], correct:3, solution:'A physical property is observed without changing the substance into something new. Density fits this rule because measuring density does not create a new substance.<br><br>Flammability, rusting, and reactivity with acid are chemical properties because they describe how the substance changes into different substances.'},
{id:'p19',difficulty:'easy',type:'concept',tag:'Concept', q:'Which of the following is a chemical property?', choices:['Melting point','Solubility in water','Ability to combust (burn)','Electrical conductivity'], correct:2, solution:'A chemical property describes how a substance reacts to form new substances. Combustion (burning) produces new compounds (CO2, H2O). Melting point, solubility, and conductivity are physical properties — no new substance is formed when you observe them.'},
  {id:'p20',difficulty:'easy',type:'concept',tag:'Concept', q:'Ice melting to form liquid water is:', choices:['A chemical change, because the water looks different','A physical change, because H2O remains H2O','A chemical change, because energy is absorbed','A nuclear change, because atoms rearrange'], correct:1, solution:'Melting is a phase change, so it is a physical change. The particles are still H2O before and after the change.<br><br>No new substance forms, and the process can be reversed by freezing the water again.'},
{id:'p21',difficulty:'easy',type:'concept',tag:'Concept', q:'Wood burning in a campfire is:', choices:['A physical change because the wood gets smaller','A chemical change because new substances (CO2, H2O, ash) are produced','A physical change because heat is released','A nuclear change because atoms rearrange'], correct:1, solution:'Combustion is a chemical change — the original substance (wood cellulose) is permanently converted into completely different substances: carbon dioxide, water vapor, and ash. Signs: new substances, light and heat released, irreversible.'},
{id:'p22',difficulty:'medium',type:'concept',tag:'Concept', q:'Which observation is BEST evidence of a chemical change?', choices:['A substance changes color when painted','Ice changes from solid to liquid','A gas bubble forms when two clear solutions are mixed','Sugar dissolves in water'], correct:2, solution:'Gas production when two solutions are mixed indicates a chemical reaction has produced a new substance (a gas). Color change from painting, phase change, and dissolving are all physical changes — no new chemical substances are formed.'},
{id:'p23',difficulty:'easy',type:'concept',tag:'Concept', q:'Dissolving sugar in water is:', choices:['A chemical change because you cannot see the sugar anymore','A physical change because the sugar can be recovered by evaporating the water','A chemical change because the solution tastes sweet','A nuclear change because sugar molecules split apart'], correct:1, solution:'Dissolving is a physical change — the sugar molecules are dispersed between water molecules but are not chemically altered. Evaporate the water and you recover the original sugar. No new substance is produced.'},
{id:'p24',difficulty:'easy',type:'concept',tag:'Concept', q:'Which of the following is a chemical change?', choices:['Cutting paper into small pieces','Bending a copper wire','Iron rusting in the presence of water and oxygen','Boiling water to produce steam'], correct:2, solution:'Rusting is a chemical change: iron (Fe) reacts with oxygen and water to form iron oxide (Fe2O3), a new substance with completely different properties. Cutting, bending, and boiling are physical changes — the chemical identity is preserved.'},
{id:'p25',difficulty:'medium',type:'concept',tag:'Concept', q:'Which is NOT a sign that a chemical change may have occurred?', choices:['Formation of a precipitate','Change of state (melting)','Permanent color change','Release of gas'], correct:1, solution:'Change of state is a physical change — the substance retains its chemical identity through melting, boiling, or freezing. Precipitate formation, permanent color change, and gas release all indicate new substances have been produced (chemical change).'},
{id:'p26',difficulty:'easy',type:'concept',tag:'Concept', q:'Copper is beaten into a thin sheet (copper foil). This is a:', choices:['Chemical change, because the shape changed','Physical change, because copper remains copper','Chemical change, because heat may be involved','Nuclear change, because the atoms rearrange'], correct:1, solution:'Malleability (being beaten into a sheet) is a physical change. The copper atoms are repositioned, but no new substance is created — the material is still copper (Cu). Physical changes do not alter chemical identity.'},
{id:'p27',difficulty:'easy',type:'concept',tag:'Concept', q:'The density of a substance is 2.7 g/mL. This is best described as:', choices:['A chemical property, because it involves mass','A physical property, because it can be measured without a chemical reaction','A chemical property, because density changes when state changes','A nuclear property'], correct:1, solution:'Density (mass/volume) is a physical property — you measure mass and volume without causing any chemical reaction. No new substances are produced in the measurement.'},
{id:'p28',difficulty:'medium',type:'concept',tag:'Concept', q:'Tarnishing of silver involves silver reacting with sulfur compounds in air to form Ag2S. This is:', choices:['A physical change, because the silver still exists','A chemical change, because a new substance (silver sulfide) forms','A physical change, because it happens slowly','A nuclear change, because sulfur bonds to silver'], correct:1, solution:'Tarnishing is a chemical change. Silver (Ag) reacts with hydrogen sulfide to form silver sulfide (Ag2S), an entirely different compound with different properties (black, dull). The original silver is no longer present as silver.'},
{id:'p29',difficulty:'medium',type:'concept',tag:'Concept', q:'Which of the following is an extensive property?', choices:['Density','Boiling point','Mass','Color'], correct:2, solution:'An extensive property depends on the amount of matter present. Mass, volume, and energy content are extensive — double the sample, double the mass. Density, boiling point, and color are intensive properties — they are the same regardless of sample size.'},
{id:'p30',difficulty:'medium',type:'concept',tag:'Concept', q:'Which of the following is an intensive property?', choices:['Volume','Mass','Number of atoms','Melting point'], correct:3, solution:'An intensive property does not depend on the amount of matter. Melting point is the same whether you have 1 g or 1 kg of a substance. Volume, mass, and number of atoms all change with sample size (extensive).'},
{id:'p31',difficulty:'easy',type:'concept',tag:'Concept', q:'When hydrogen gas burns, it combines with oxygen to form water. This is:', choices:['A physical change, because water is a familiar substance','A chemical change, because new covalent bonds form between H and O','A physical change, because no color change occurs','A nuclear change, because hydrogen is involved in nuclear fusion'], correct:1, solution:'Combustion of hydrogen is a chemical change: H2 and O2 react to form H2O, a new compound with completely different properties. New chemical bonds form — a hallmark of a chemical change.'},
{id:'p32',difficulty:'medium',type:'concept',tag:'Concept', q:'A chemical property of hydrogen gas is that it:', choices:['Is a colorless gas at room temperature','Has a density less than air','Is flammable and reacts explosively with oxygen','Liquefies at -253°C'], correct:2, solution:'Flammability (ability to react with oxygen) is a chemical property — it describes how hydrogen transforms into a new substance (water) when it reacts. Colorless, density, and liquefying temperature are physical properties.'},
{id:'p33',difficulty:'medium',type:'concept',tag:'Concept', q:'Which best explains why distillation separates ethanol from water?', choices:['Ethanol and water have different densities','Ethanol and water have different boiling points','Ethanol and water have different colors','Ethanol reacts with water during distillation'], correct:1, solution:'Distillation exploits different boiling points. Ethanol (bp 78°C) boils before water (bp 100°C), so it vaporizes first and is collected as a separate, purer fraction. This is a physical separation — no new substances are formed.'},
{id:'p34',difficulty:'medium',type:'concept',tag:'Concept', q:'An unknown substance has a fixed melting point of 801°C regardless of sample size. This suggests:', choices:['It is a mixture with a range of melting temperatures','It is a pure substance with a definite, sharp melting point','It has a high density','It is a heterogeneous mixture'], correct:1, solution:'Pure substances have sharp, fixed melting and boiling points. A definite melting point at 801°C (like NaCl) is diagnostic of a pure substance. Mixtures melt over a range of temperatures because different components have different melting points.'},
{id:'p35',difficulty:'easy',type:'concept',tag:'Concept', q:'Which change is reversible under normal laboratory conditions?', choices:['Wood burning','Iron rusting','Water evaporating','Egg cooking'], correct:2, solution:'Water evaporating is a physical change — it is reversed by condensation. Burning, rusting, and cooking are chemical changes that produce new substances and cannot be easily reversed by physical means under normal lab conditions.'},
{id:'p36',difficulty:'easy',type:'concept',tag:'Concept', q:'A student tears a piece of paper in half, then burns one half. Which statement is correct?', choices:['Both are chemical changes.','Both are physical changes.','Tearing is physical; burning is chemical.','Tearing is chemical; burning is physical.'], correct:2, solution:'Tearing is a physical change — paper is still paper, just smaller pieces. Burning is a chemical change — the paper cellulose is converted to CO2, H2O, and ash. Only burning produces new chemical substances.'},

/* ══════════════ CONCEPT — Particle Diagrams (10) ══════════════ */
{id:'p37',difficulty:'easy',type:'concept',tag:'Concept', q:'This particle diagram shows only one type of atom, all separate (not bonded). This represents:', diagram:'images/practice-u02-monatomic-element.svg', diagramAlt:'Particle diagram showing only one type of unbonded atom in a container.', diagramCaption:'One atom type appears throughout, and none of the particles are bonded.', choices:['A compound','A monatomic element','A diatomic molecule','A mixture'], correct:1, solution:'A single type of atom, unbonded, is a monatomic element — like noble gases (He, Ne, Ar). Each particle is a single atom. No bonds = not a molecule; one type of atom = element, not a mixture or compound.'},
{id:'p38',difficulty:'medium',type:'concept',tag:'Concept', q:'This particle diagram shows pairs of identical atoms bonded together. This represents:', diagram:'images/practice-u02-diatomic-element.svg', diagramAlt:'Particle diagram showing identical atoms bonded in pairs throughout the container.', diagramCaption:'Every particle is the same bonded pair, so only one atom type is present.', choices:['A compound','A mixture of two elements','A diatomic element in molecular form','A monatomic element'], correct:2, solution:'Identical atoms bonded in pairs = a diatomic element (like O2, N2, H2, Cl2). The substance is still an element because only one type of atom is present, even though the atoms are bonded into molecules.'},
{id:'p39',difficulty:'medium',type:'concept',tag:'Concept', q:'This particle diagram shows a 2:1 repeating pattern of two different types of atoms bonded together. This represents:', diagram:'images/practice-u02-compound-2to1.svg', diagramAlt:'Particle diagram showing identical bonded groups made from two atom types in a repeating two to one ratio.', diagramCaption:'Each group has the same bonded ratio, which is the signature of a compound.', choices:['A heterogeneous mixture','A compound with a fixed ratio','A homogeneous mixture','A monatomic element'], correct:1, solution:'Two different atom types bonded in a fixed ratio = a compound. The ratio (2:1 here) is the empirical formula of the compound. Bonding is the key distinction from a mixture.'},
{id:'p40',difficulty:'medium',type:'concept',tag:'Concept', q:'This particle diagram shows different particle types freely mixed, not bonded to each other. This represents:', diagram:'images/practice-u02-mixture-uniform.svg', diagramAlt:'Particle diagram showing different particle types mixed evenly without bonding between unlike particles.', diagramCaption:'Different particles share the same container, but they are not chemically bonded to one another.', choices:['A compound','An element','A mixture','A pure substance with two isotopes'], correct:2, solution:'Two types of molecules mixed but not chemically bonded = a mixture. The components retain their individual identities and could theoretically be separated by physical means.'},
{id:'p41',difficulty:'medium',type:'concept',tag:'Concept', q:'In a particle diagram, what is the key feature that distinguishes a compound from a mixture of two elements?', choices:['The number of atoms shown','Whether different atom types are present','Whether the atoms are bonded together in fixed ratios','The color used to represent each atom'], correct:2, solution:'Both a compound and a mixture of two elements have more than one type of atom. The distinguishing feature is bonding: in a compound, different atoms are chemically bonded in fixed ratios. In a mixture, atoms or molecules of different types coexist without chemical bonds between them.'},
{id:'p42',difficulty:'easy',type:'concept',tag:'Concept', q:'This particle diagram shows clusters of one particle type on one side and a different particle type on the other side, not uniformly mixed. This is:', diagram:'images/practice-u02-mixture-heterogeneous.svg', diagramAlt:'Particle diagram showing one particle type concentrated in the top region and another in the bottom region.', diagramCaption:'The sample composition changes from one region to another instead of staying uniform.', choices:['A homogeneous mixture','A heterogeneous mixture','A compound','An element'], correct:1, solution:'Non-uniform distribution of two types of molecules = a heterogeneous mixture. The composition varies from region to region within the sample, unlike a solution (homogeneous) where molecules are uniformly distributed.'},
{id:'p43',difficulty:'medium',type:'concept',tag:'Concept', q:'Which particle diagram best represents a pure element in its diatomic form?', diagram:'images/practice-u02-diatomic-element.svg', diagramAlt:'Particle diagram showing only identical bonded pairs in a container.', diagramCaption:'Only one atom type is present, and each particle appears as a bonded pair.', choices:['Single atoms, one type','Pairs of identical atoms bonded together','Pairs of different atoms bonded together','A mix of single atoms of two different types'], correct:1, solution:'Diatomic elements (H2, O2, N2, F2, Cl2, Br2, I2) are represented as pairs of identical atoms bonded together. One type of atom + bonded in pairs = diatomic element.'},
{id:'p44',difficulty:'medium',type:'concept',tag:'Concept', q:'This diagram shows molecules made from one red atom bonded to two blue atoms. All molecules are identical. This substance is:', diagram:'images/practice-u02-compound-2to1.svg', diagramAlt:'Particle diagram showing identical molecules built from two atom types in a fixed two to one ratio.', diagramCaption:'When every particle has the same bonded composition, the sample is a pure compound.', choices:['A mixture of a red element and a blue element','A compound with a 1:2 red-to-blue ratio','A heterogeneous mixture','An element with two isotopes'], correct:1, solution:'Identical molecules, each containing two different types of atoms in a fixed ratio (1:2) = a pure compound. No mixing of different molecule types = not a mixture.'},
{id:'p45',difficulty:'easy',type:'concept',tag:'Concept', q:'Why is this particle diagram of a solution like salt water considered homogeneous?', diagram:'images/practice-u02-saltwater.svg', diagramAlt:'Particle diagram showing Na+ and Cl- ions evenly dispersed throughout a container.', diagramCaption:'The dissolved ions are spread evenly throughout the sample instead of separating into regions.', choices:['Because salt and water react to form a new compound','Because the Na^+ and Cl^- ions are uniformly distributed throughout the water','Because you cannot see the particles','Because both components are the same color'], correct:1, solution:'A solution is homogeneous because the solute particles (Na^+ and Cl^- ions) are dispersed uniformly at the molecular/ionic level throughout the solvent. Every part of the sample has the same composition.'},
{id:'p46',difficulty:'medium',type:'concept',tag:'Concept', q:'This particle diagram shows several particle types freely moving and uniformly distributed. This gas is:', diagram:'images/practice-u02-mixture-uniform.svg', diagramAlt:'Particle diagram showing several particle types spread evenly through a gas sample.', diagramCaption:'Multiple particle types are present, but the spacing stays even across the whole sample.', choices:['A compound','An element','A heterogeneous mixture','A homogeneous mixture'], correct:3, solution:'Three types of molecules uniformly distributed = a homogeneous mixture. Air is an example — N2, O2, and Ar are uniformly mixed at the molecular level, making air a homogeneous mixture (solution) in the gas phase.'},

/* ══════════════ CALCULATION (10) ══════════════ */
{id:'p47',difficulty:'easy',type:'calc',tag:'Formula Counting', q:'How many total atoms are in 3 molecules of H2O?', answer:9, tolerance:0.01, solution:'Each H2O molecule has 2 H + 1 O = 3 atoms total. For 3 molecules: 3 × 3 = <strong>9 atoms</strong>.'},
{id:'p48',difficulty:'easy',type:'calc',tag:'Formula Counting', q:'How many oxygen atoms are in 5 formula units of Fe2O3?', answer:15, tolerance:0.01, solution:'One formula unit of Fe2O3 contains 3 oxygen atoms. For 5 formula units: 5 × 3 = <strong>15 oxygen atoms</strong>.'},
{id:'p49',difficulty:'easy',type:'calc',tag:'Formula Counting', q:'How many total atoms are in 1 formula unit of C6H12O6?', answer:24, tolerance:0.01, solution:'Count all atoms in the formula: 6 C + 12 H + 6 O = <strong>24 atoms</strong> total.'},
{id:'p50',difficulty:'easy',type:'calc',tag:'Formula Counting', q:'How many chlorine atoms are in 4 formula units of CaCl2?', answer:8, tolerance:0.01, solution:'Each formula unit of CaCl2 contains 2 chlorine atoms. For 4 formula units: 4 × 2 = <strong>8 chlorine atoms</strong>.'},
{id:'p51',difficulty:'easy',type:'calc',tag:'Formula Counting', q:'How many different atom types are present in NH4NO3?', answer:3, tolerance:0.01, solution:'NH4NO3 contains nitrogen (N), hydrogen (H), and oxygen (O). That is <strong>3 different atom types</strong>.'},
{id:'p52',difficulty:'medium',type:'calc',tag:'Formula Counting', q:'How many sulfur atoms are in 2 formula units of Al2(SO4)3?', answer:6, tolerance:0.01, solution:'One formula unit of Al2(SO4)3 has 3 sulfate groups, so it contains 3 sulfur atoms. For 2 formula units: 2 × 3 = <strong>6 sulfur atoms</strong>.'},
{id:'p53',difficulty:'easy',type:'calc',tag:'Formula Counting', q:'How many total atoms are in 1 formula unit of NaHCO3?', answer:6, tolerance:0.01, solution:'Count the atoms: 1 Na + 1 H + 1 C + 3 O = <strong>6 atoms</strong> total.'},
{id:'p54',difficulty:'easy',type:'calc',tag:'Formula Counting', q:'How many oxygen atoms are in 3 molecules of CO2?', answer:6, tolerance:0.01, solution:'Each CO2 molecule contains 2 oxygen atoms. For 3 molecules: 3 × 2 = <strong>6 oxygen atoms</strong>.'},
{id:'p55',difficulty:'medium',type:'calc',tag:'Formula Counting', q:'How many total atoms are in 1 formula unit of Fe(NO3)3?', answer:13, tolerance:0.01, solution:'Fe(NO3)3 contains 1 Fe atom. The nitrate group appears 3 times, giving 3 N and 9 O. Total atoms = 1 + 3 + 9 = <strong>13 atoms</strong>.'},
{id:'p56',difficulty:'easy',type:'calc',tag:'Formula Counting', q:'How many total atoms are in 2 molecules of H2SO4?', answer:14, tolerance:0.01, solution:'One H2SO4 molecule has 2 H + 1 S + 4 O = 7 atoms. For 2 molecules: 2 × 7 = <strong>14 atoms</strong>.'},

/* ══════════════ MULTI-STEP (10) ══════════════ */
{id:'p57',difficulty:'hard',type:'multi',tag:'Multi-step', q:'Three flasks are labeled as follows: Flask A contains only O2 molecules. Flask B contains only CO2 molecules. Flask C contains both O2 and CO2 molecules spread evenly together. Which statement correctly classifies all three?', choices:['A is an element, B is a compound, C is a homogeneous mixture','A is a compound, B is an element, C is a heterogeneous mixture','A is an element, B is a mixture, C is a compound','A is a homogeneous mixture, B is a pure substance, C is a heterogeneous mixture'], correct:0, solution:'Flask A is an <strong>element</strong> because every particle contains only oxygen atoms. Flask B is a <strong>compound</strong> because carbon and oxygen are chemically bonded in a fixed ratio. Flask C contains two different particle types spread evenly, so it is a <strong>homogeneous mixture</strong>.'},
{id:'p58',difficulty:'hard',type:'multi',tag:'Multi-step', q:'A student studies two particle diagrams. Diagram 1 shows only identical blue-blue bonded pairs. Diagram 2 shows blue-blue pairs and red-black-red molecules spread uniformly together. Which answer best describes the two diagrams?', choices:['Diagram 1 = element; Diagram 2 = homogeneous mixture','Diagram 1 = compound; Diagram 2 = element','Diagram 1 = heterogeneous mixture; Diagram 2 = compound','Diagram 1 = element; Diagram 2 = heterogeneous mixture'], correct:0, solution:'Diagram 1 is an <strong>element</strong> because the bonded pairs are made of only one atom type. Diagram 2 contains <strong>more than one particle type</strong>, so it is a mixture, and the even spread makes it <strong>homogeneous</strong>.'},
{id:'p59',difficulty:'medium',type:'multi',tag:'Multi-step', q:'A student classifies these items: (1) baking soda dissolved in water, (2) a bowl of trail mix, (3) pure nitrogen gas, (4) table sugar (C12H22O11). Which correctly pairs each with its classification?', choices:['1-compound, 2-heterogeneous mixture, 3-element, 4-compound','1-homogeneous mixture, 2-heterogeneous mixture, 3-element, 4-compound','1-element, 2-compound, 3-mixture, 4-element','1-compound, 2-compound, 3-element, 4-mixture'], correct:1, solution:'(1) Baking soda dissolved in water = homogeneous mixture (solution). (2) Trail mix = heterogeneous mixture (visibly different components). (3) Pure N2 = element. (4) C12H22O11 = compound (fixed ratio of C, H, O).'},
{id:'p60',difficulty:'medium',type:'multi',tag:'Multi-step', q:'Classify each process as a physical change (P) or chemical change (C): melting ice, burning gasoline, dissolving salt, fermenting sugar into alcohol.', choices:['P, C, P, C','C, C, P, P','P, P, C, C','C, P, C, P'], correct:0, solution:'Melting ice → P (H2O stays H2O, just phase change). Burning gasoline → C (new substances: CO2, H2O). Dissolving salt → P (NaCl disperses but is unchanged, recovered by evaporation). Fermenting sugar → C (C6H12O6 → C2H5OH + CO2, new compounds formed).'},
{id:'p61',difficulty:'medium',type:'multi',tag:'Multi-step', q:'A pure substance melts sharply at 660°C, conducts electricity, and can be hammered into thin sheets. Its formula is Al. What type of substance is this, and which classification fits best?', choices:['Nonmetal compound','Metalloid mixture','Metal element','Heterogeneous mixture'], correct:2, solution:'A sharp melting point and one chemical symbol indicate a <strong>pure substance</strong>. The formula Al means only one atom type is present, so it is an <strong>element</strong>. Conductivity and malleability are metallic properties, so the best classification is <strong>metal element</strong>.'},
{id:'p62',difficulty:'hard',type:'multi',tag:'Multi-step', q:'A student has a mixture of salt, sand, and iron filings. Describe the correct order of physical separation methods to isolate all three components.', choices:['Filter → magnet → evaporate','Magnet (iron) → dissolve in water then filter (sand) → evaporate (salt)','Evaporate → filter → magnet','Distill → chromatography → filtration'], correct:1, solution:'Step 1: Use a magnet to remove iron filings (magnetic, separates without affecting salt or sand). Step 2: Add water — salt dissolves, sand does not. Filter to remove sand. Step 3: Evaporate the salt water to recover salt. Each step uses a different physical property.'},
{id:'p63',difficulty:'hard',type:'multi',tag:'Multi-step', q:'A student writes these labels for three samples: (1) NaCl(s) = homogeneous mixture because it contains two elements, (2) air = homogeneous mixture, (3) O2(g) = compound because the atoms are bonded. Which evaluation is correct?', choices:['Only 1 is correct','Only 2 is correct','2 and 3 are correct','All three are correct'], correct:1, solution:'(1) is incorrect because NaCl is a <strong>compound</strong>, not a mixture. The two elements are chemically bonded in a fixed ratio. (2) is correct because air is a <strong>homogeneous mixture</strong> of gases. (3) is incorrect because O2 is still an <strong>element</strong>; bonded identical atoms do not make a compound.'},
{id:'p64',difficulty:'medium',type:'multi',tag:'Multi-step', q:'A substance has these properties: boiling point 78°C, is flammable, mixes with water in all proportions, and has molecular formula C2H5OH. Based on this information, what is the best classification and property pairing?', choices:['Element; boiling point is physical and flammability is chemical','Compound; boiling point is physical and flammability is chemical','Mixture; mixing with water is chemical and flammability is physical','Element; mixing with water is physical and boiling point is chemical'], correct:1, solution:'C2H5OH contains carbon, hydrogen, and oxygen bonded in a fixed ratio, so it is a <strong>compound</strong>. Boiling point and mixing with water are <strong>physical properties</strong> because no new substance forms when you observe them. Flammability is a <strong>chemical property</strong> because burning forms new substances.'},
{id:'p65',difficulty:'medium',type:'multi',tag:'Multi-step', q:'Is the following change physical or chemical? Explain: When a raw egg is cooked, the clear egg white turns solid and white, and this change cannot be reversed.', choices:['Physical — the egg just changed state like melting','Chemical — proteins denature forming new cross-links; the change is irreversible','Physical — heat is a physical factor','Chemical — the color change from clear to white indicates a new element formed'], correct:1, solution:'Cooking an egg is a chemical change. The egg white proteins (albumin) undergo irreversible denaturation — they unfold and form new cross-linked structures with different properties. Evidence: new appearance (clear → white, liquid → solid), irreversibility, change in texture and chemical structure.'},
{id:'p66',difficulty:'medium',type:'multi',tag:'Multi-step', q:'A mystery liquid has a fixed boiling point of 100°C and the formula H2O. A mystery solid melts over a range of 50–80°C and contains visible particles. Which statement is best?', choices:['Both samples are pure substances','Liquid is a pure substance; solid is a mixture','Solid is a pure substance; liquid is a mixture','Both samples are mixtures'], correct:1, solution:'A fixed boiling point and a definite formula indicate the liquid is a <strong>pure substance</strong>. A melting range and visible particles indicate the solid is a <strong>mixture</strong>, most likely heterogeneous because the composition is not uniform.'},

/* ══════════════ CONCEPT — Additional Classification (4) ══════════════ */
{id:'p67', difficulty:'easy', type:'concept', tag:'Classification', q:'Which of the following correctly lists three examples of elements?', choices:['Water, salt, oxygen','Iron, gold, neon','Sulfuric acid, ammonia, methane','Steel, bronze, brass'], correct:1, solution:'Iron (Fe), gold (Au), and neon (Ne) are all pure elements — each is made of only one type of atom and appears on the periodic table. Water (H2O) and salt (NaCl) are compounds. Sulfuric acid, ammonia, and methane are compounds. Steel, bronze, and brass are alloys (mixtures).'},
{id:'p68', difficulty:'medium', type:'concept', tag:'Classification', q:'An alloy is a mixture of two or more metals. Which of the following correctly classifies steel (iron + carbon)?', choices:['A compound, because iron and carbon are chemically bonded in a fixed ratio','A homogeneous mixture, because the components are uniformly distributed','A heterogeneous mixture, because you can see iron and carbon separately','A pure element, because it has metallic properties'], correct:1, solution:'Steel is a homogeneous mixture (alloy) — the carbon atoms are uniformly distributed throughout the iron lattice, but no fixed chemical formula exists for steel. Its composition can vary (low-carbon vs. high-carbon steel), which is characteristic of a mixture, not a compound.'},
{id:'p69', difficulty:'easy', type:'concept', tag:'Separation', q:'A mixture of two liquids is separated by distillation. What physical property is exploited?', choices:['Density','Boiling point','Particle size','Magnetic susceptibility'], correct:1, solution:'Distillation separates liquids based on different boiling points. The more volatile component (lower boiling point) vaporizes first, travels through a condenser, and is collected as a separate pure liquid. No chemical change occurs.'},
{id:'p70', difficulty:'easy', type:'concept', tag:'Pure Substances', q:'Which of the following statements about pure substances is correct?', choices:['They always consist of only one element','They have variable composition depending on how they are prepared','They have definite, fixed properties regardless of their source or sample size','They can always be separated by filtration'], correct:2, solution:'Pure substances — whether elements or compounds — have definite, fixed properties (melting point, boiling point, density, etc.) that do not depend on sample size or origin. A pure compound like H2O has the same properties anywhere in the universe. Variable composition is the hallmark of a mixture.'},

/* ══════════════ CONCEPT — Additional Properties & Changes (3) ══════════════ */
{id:'p71', difficulty:'easy', type:'concept', tag:'Properties', q:'Which of the following observations is most consistent with a chemical change having occurred?', choices:['A solid dissolves when stirred into a liquid','A liquid evaporates when left in an open container','A colorless solution produces a yellow precipitate when a second solution is added','A metal rod is bent into a curve'], correct:2, solution:'Precipitate formation — a solid appearing from two mixed solutions — is strong evidence of a chemical change because a new substance (the precipitate) that was not present before has formed. Dissolving, evaporating, and bending are physical changes.'},
{id:'p72', difficulty:'medium', type:'concept', tag:'Properties', q:'The boiling point of a substance is 357°C regardless of sample size. This property is best classified as:', choices:['Extensive, because temperature involves energy','Intensive, because it does not depend on the amount of matter','Extensive, because it changes with pressure','Chemical, because boiling involves energy changes'], correct:1, solution:'Boiling point is an intensive property — it is the same for 1 mL or 1 L of the substance. Intensive properties (density, melting point, boiling point, color) are characteristic of the substance and useful for identification. Extensive properties (mass, volume) depend on sample size.'},
{id:'p73', difficulty:'medium', type:'concept', tag:'Changes', q:'A student notices that after mixing two solutions, the container feels noticeably warmer. This observation is:', choices:['Proof that a physical change occurred because temperature changed','Evidence that a chemical reaction may have occurred because energy was released','Proof that the solution boiled','Not meaningful evidence of any change'], correct:1, solution:'A temperature change (heat released or absorbed) when two substances are mixed is evidence of a chemical reaction — chemical changes involve making and breaking chemical bonds, which releases or absorbs energy. While not conclusive on its own, it is a recognized indicator of chemical change.'},

/* ══════════════ CALCULATION — Additional (3) ══════════════ */
{id:'p74', difficulty:'easy', type:'calc', tag:'Formula Counting', q:'How many different atom types are present in Ca(OH)2?', answer:3, tolerance:0.01, solution:'Ca(OH)2 contains calcium (Ca), oxygen (O), and hydrogen (H). That is <strong>3 different atom types</strong>.'},
{id:'p75', difficulty:'easy', type:'calc', tag:'Formula Counting', q:'How many oxygen atoms are in 4 formula units of Ca(OH)2?', answer:8, tolerance:0.01, solution:'One formula unit of Ca(OH)2 contains 2 oxygen atoms because the OH group appears twice. For 4 formula units: 4 × 2 = <strong>8 oxygen atoms</strong>.'},
{id:'p76', difficulty:'medium', type:'calc', tag:'Formula Counting', q:'How many total atoms are in 1 formula unit of (NH4)2SO4?', answer:15, tolerance:0.01, solution:'The formula has 2 N, 8 H, 1 S, and 4 O atoms. Total atoms = 2 + 8 + 1 + 4 = <strong>15 atoms</strong>.'},

/* ══════════════ MULTI-STEP — Additional (5) ══════════════ */
{id:'p77', difficulty:'medium', type:'multi', tag:'Formula Reading', q:'Which statement about the formula Al2(SO4)3 is correct?', choices:['It is a mixture because it has three element symbols','It is a compound containing 2 Al, 3 S, and 12 O atoms per formula unit','It is an element because aluminum is listed first','It shows aluminum and sulfate physically mixed in any ratio'], correct:1, solution:'Al2(SO4)3 is a <strong>compound</strong>, not a mixture, because the formula gives one fixed composition. The sulfate group appears 3 times, so the full atom count is 2 Al, 3 S, and 12 O atoms per formula unit.'},
{id:'p78', difficulty:'hard', type:'multi', tag:'Classification', q:'A student encounters four samples in lab: (A) a shiny solid that bends without breaking and conducts electricity, (B) a clear liquid with a fixed boiling point that does not conduct electricity, (C) a granular white powder that dissolves completely in water leaving no residue, (D) a translucent solid with visible layers of different minerals. Which is the heterogeneous mixture?', choices:['Sample A','Sample B','Sample C','Sample D'], correct:3, solution:'Sample D has visible layers of different minerals — that non-uniform composition with identifiable different components is the definition of a heterogeneous mixture (like granite). Sample A is a metal (pure substance). Sample B is likely a pure molecular compound. Sample C is likely a pure ionic compound that dissolves completely.'},
{id:'p79', difficulty:'medium', type:'multi', tag:'Changes', q:'A student performs two experiments: (1) dissolves copper sulfate crystals in water to make a blue solution, then evaporates the water to recover the original blue crystals; (2) heats copper metal in air and observes the surface turn black permanently. Which statement is correct?', choices:['Both are chemical changes because new appearances result','Experiment 1 is physical; Experiment 2 is chemical','Both are physical changes because no gases are formed','Experiment 1 is chemical; Experiment 2 is physical'], correct:1, solution:'Experiment 1: Dissolving and recovering copper sulfate is a physical change — the compound is unchanged, just dispersed then re-concentrated. Experiment 2: Copper reacting with oxygen to form copper(II) oxide (CuO, a black solid) is a chemical change — a new compound forms permanently. Reversibility is key: physical changes can be undone, chemical changes generally cannot.'},
{id:'p80', difficulty:'medium', type:'multi', tag:'Separation & Changes', q:'A student stirs salt into water, filters the clear solution, then evaporates the water. Which statement best describes what happens?', choices:['Filtering removes the dissolved salt, and evaporation is a chemical change','Filtering does not remove dissolved salt, and evaporation is a physical change that leaves salt behind','Dissolving salt is a chemical change, so the salt cannot be recovered','Evaporation produces a new substance, so the final solid is not NaCl'], correct:1, solution:'Filtering cannot remove dissolved salt because the ions are spread through the water at the particle level. Evaporation is a <strong>physical change</strong> that removes water and leaves the original salt behind, so the salt can be recovered.'},
{id:'p81', difficulty:'medium', type:'multi', tag:'Classification & Changes', q:'Table salt (NaCl) is dissolved in water, the solution is poured through a filter, and then the water is evaporated. What happens at each step, and what type of change is each?', choices:['Dissolving: chemical; filtering: physical; evaporating: chemical','Dissolving: physical; filtering: physical; evaporating: physical','Dissolving: chemical; filtering: chemical; evaporating: physical','Dissolving: physical; filtering: chemical; evaporating: chemical'], correct:1, solution:'Dissolving NaCl: physical change — the ions separate and disperse, but NaCl is recovered intact. Filtering: physical change — the filter separates by particle size; no new substances form. Evaporating water: physical change — water changes phase from liquid to gas, but both water and salt retain their chemical identities. All three steps are physical changes that together describe how to purify a dissolved salt.'},

/* ══════════════ CONCEPT — Particle Diagram: New SVG Set (5) ══════════════ */
{id:'p82', difficulty:'easy', type:'concept', tag:'Particle Diagram', q:'This particle diagram shows only one kind of large atom spread throughout a solid sample — all identical, none bonded to a different type. What is the best classification?', diagram:'images/practice-u02-element-Au.svg', diagramAlt:'Particle diagram showing six identical large gold-colored atoms, all unbonded, in a container.', diagramCaption:'Every particle in the sample is the same atom type, and none are bonded to a different kind.', choices:['Element','Compound','Homogeneous mixture','Heterogeneous mixture'], correct:0, solution:'One atom type, all unbonded = pure element. A solid metal like gold (Au) at the particle level looks exactly like this — identical atoms with no second element bonded in. The color or size of the atom does not change the classification: one type, no bonding to another type = element.'},
{id:'p83', difficulty:'easy', type:'concept', tag:'Particle Diagram', q:'This particle diagram shows only one kind of tiny atom spread throughout a gas sample — all identical, none bonded to anything. What is the best classification?', diagram:'images/practice-u02-element-He.svg', diagramAlt:'Particle diagram showing eight identical small lavender atoms, all unbonded, spread throughout a container.', diagramCaption:'One small atom type fills the container; none are bonded to another particle.', choices:['Element','Compound','Homogeneous mixture','Heterogeneous mixture'], correct:0, solution:'Noble gases (He, Ne, Ar, Kr) exist as single, unbonded atoms — this is the monatomic form of an element. One atom type, completely unbonded = element. The small size and dispersed arrangement are typical of a gas-phase element, not a compound or mixture.'},
{id:'p84', difficulty:'easy', type:'concept', tag:'Particle Diagram', q:'This diagram shows identical bent three-atom molecules throughout the sample — each with one large red atom bonded to two smaller atoms. What is the best classification?', diagram:'images/practice-u02-compound-H2O.svg', diagramAlt:'Particle diagram showing four identical bent molecules, each with one large red atom bonded to two smaller gray atoms.', diagramCaption:'Every particle is the same bonded unit: two different atom types in a fixed bent arrangement.', choices:['Element','Compound','Homogeneous mixture','Heterogeneous mixture'], correct:1, solution:'Two different atom types are chemically bonded in the same fixed ratio in every particle (1 large : 2 small). One repeating bonded particle made from different atom types = compound. This is the structure of water (H2O). The key distinction from a mixture: every particle is identical, not a random combination of different molecules.'},
{id:'p85', difficulty:'easy', type:'concept', tag:'Particle Diagram', q:'This diagram shows identical bonded pairs throughout the sample — each pair has one purple atom and one teal atom in a fixed 1:1 ratio. What is the best classification?', diagram:'images/practice-u02-compound-NaCl.svg', diagramAlt:'Particle diagram showing four identical bonded pairs, each with one purple atom touching one teal atom.', diagramCaption:'Only one type of bonded unit appears; the ratio of purple to teal is always 1:1.', choices:['Element','Compound','Homogeneous mixture','Heterogeneous mixture'], correct:1, solution:'Two different atom types bonded in a fixed 1:1 ratio = compound. This is the structure of an ionic compound like NaCl. A common misconception is that the presence of two different ions makes it a mixture — it does not. The ions are chemically bonded in a definite ratio, which is the definition of a compound.'},
{id:'p86', difficulty:'easy', type:'concept', tag:'Particle Diagram', q:'This diagram shows identical linear molecules in a gas sample — each has one large dark atom in the center bonded to two red atoms on either side. What is the best classification?', diagram:'images/practice-u02-compound-CO2.svg', diagramAlt:'Particle diagram showing three identical linear molecules, each with a large dark center atom bonded to two smaller red atoms.', diagramCaption:'Every molecule is linear with two different atom types — two red outer atoms and one dark center atom.', choices:['Element','Compound','Homogeneous mixture','Heterogeneous mixture'], correct:1, solution:'Two different atom types (dark center, red outer) are bonded in a fixed ratio in every molecule (1 center : 2 outer). One repeating bonded molecule with different atom types = compound. This is the structure of CO2. Do not confuse this with a diatomic element — a diatomic element has the same atom type on both sides; this molecule has two different atom types.'},

/* ══════════════ EXPANSION BATCH — 60 problems (20 easy / 25 medium / 15 hard) ══════════════ */

/* ── EASY (20) ── */
{id:'p87',difficulty:'easy',type:'concept',tag:'Concept',q:'Which of the following is a mixture?',choices:['Diamond (C)','Graphite (C)','Air','Sodium chloride (NaCl)'],correct:2,solution:'Air is a blend of gases (N2, O2, Ar, and others) uniformly mixed — a homogeneous mixture. Diamond and graphite are both pure carbon (an element, in different structural forms). NaCl is a compound.'},
{id:'p88',difficulty:'easy',type:'concept',tag:'Concept',q:'Ozone (O3) is best classified as:',choices:['A compound','An element in triatomic molecular form','A heterogeneous mixture','A homogeneous mixture'],correct:1,solution:'Ozone is made of only oxygen atoms — three of them bonded together. One atom type, bonded, is still an element, just a different molecular form (allotrope) of oxygen, like O2.'},
{id:'p89',difficulty:'easy',type:'concept',tag:'Concept',q:'Diamond and graphite are both pure forms of carbon. This means they are both:',choices:['Compounds','Elements','Mixtures','Isotopes'],correct:1,solution:'Both diamond and graphite contain only carbon atoms — one type of atom means element. They are allotropes (different structural arrangements of the same element), not isotopes (same element, different neutron count) or compounds.'},
{id:'p90',difficulty:'easy',type:'concept',tag:'Separation',q:'Which separation method uses differences in density to separate immiscible liquids like oil and water?',choices:['Distillation','Decanting or using a separatory funnel','Chromatography','Magnetism'],correct:1,solution:'Oil and water do not mix and settle into layers based on density — the less dense oil floats on top. A separatory funnel lets you drain off the denser bottom layer, physically separating the two liquids.'},
{id:'p91',difficulty:'easy',type:'concept',tag:'Concept',q:'Milk looks completely uniform to the naked eye, yet it is classified as a heterogeneous mixture (a colloid). Why?',choices:['Because milk is a pure substance','Because at the microscopic level, fat globules and proteins are dispersed as distinct particles throughout the liquid, not truly dissolved','Because milk is an element','Because milk has a fixed chemical formula'],correct:1,solution:'Even though milk appears smooth, it is a colloid — fat and protein particles are suspended (not dissolved) throughout the water-based liquid. Under a microscope, or using a light beam (the Tyndall effect), the separate particles become visible.'},
{id:'p92',difficulty:'easy',type:'concept',tag:'Changes',q:'Baking soda (NaHCO3) reacting with vinegar produces fizzing bubbles of gas. This is evidence of a:',choices:['Physical change','Chemical change','Change of state only','Extensive property change'],correct:1,solution:'Gas production is a classic sign of a chemical change — baking soda and vinegar react to form new substances, including carbon dioxide gas (the bubbles), sodium acetate, and water.'},
{id:'p93',difficulty:'easy',type:'concept',tag:'Changes',q:'Freezing liquid water into ice is a:',choices:['Chemical change','Physical change','Change in composition','Nuclear change'],correct:1,solution:'Freezing is a phase change — the water molecules (H2O) are unchanged, just arranged into a solid structure. It is reversible by melting, a hallmark of a physical change.'},
{id:'p94',difficulty:'easy',type:'calc',tag:'Formula Counting',q:'How many total atoms are in 2 molecules of NH3?',answer:8,tolerance:0.01,solution:'Each NH3 molecule has 1 N + 3 H = 4 atoms. For 2 molecules: 2 × 4 = <strong>8 atoms</strong>.'},
{id:'p95',difficulty:'easy',type:'calc',tag:'Formula Counting',q:'How many hydrogen atoms are in 3 formula units of Mg(OH)2?',answer:6,tolerance:0.01,solution:'Each formula unit of Mg(OH)2 contains 2 hydrogen atoms. For 3 formula units: 3 × 2 = <strong>6 hydrogen atoms</strong>.'},
{id:'p96',difficulty:'easy',type:'calc',tag:'Formula Counting',q:'How many total atoms are in 1 formula unit of KNO3?',answer:5,tolerance:0.01,solution:'K(1) + N(1) + O(3) = <strong>5 atoms</strong> total.'},
{id:'p97',difficulty:'easy',type:'calc',tag:'Formula Counting',q:'How many different atom types are present in C6H12O6?',answer:3,tolerance:0.01,solution:'C6H12O6 contains carbon (C), hydrogen (H), and oxygen (O) — <strong>3 different atom types</strong>.'},
{id:'p98',difficulty:'easy',type:'calc',tag:'Formula Counting',q:'How many oxygen atoms are in 2 formula units of Al2O3?',answer:6,tolerance:0.01,solution:'Each formula unit of Al2O3 has 3 oxygen atoms. For 2 formula units: 2 × 3 = <strong>6 oxygen atoms</strong>.'},
{id:'p99',difficulty:'easy',type:'concept',tag:'Properties',q:'Which of the following is an example of an intensive property?',choices:['Volume','Mass','Melting point','Length'],correct:2,solution:'Melting point does not depend on how much of a substance you have — it is intensive. Volume, mass, and length all change with sample size (extensive).'},
{id:'p100',difficulty:'easy',type:'concept',tag:'Properties',q:'Which of the following is an example of an extensive property?',choices:['Density','Boiling point','Volume','Color'],correct:2,solution:'Volume depends on how much of a substance you have — it is extensive. Density, boiling point, and color are the same regardless of sample size (intensive).'},
{id:'p101',difficulty:'easy',type:'concept',tag:'Separation',q:'A student separates iron filings from a mixture of iron and sulfur powder using a magnet. What physical property allows this separation?',choices:['Boiling point','Magnetism','Density','Solubility'],correct:1,solution:'Iron is magnetic; sulfur is not. A magnet attracts and removes the iron filings, leaving the sulfur behind, physically separating the components.'},
{id:'p102',difficulty:'easy',type:'concept',tag:'Changes',q:'Rust forming on an iron nail left outside is a:',choices:['Physical change','Chemical change','Reversible phase change','Intensive property'],correct:1,solution:'Rusting is a chemical change — iron reacts with oxygen and water to form iron oxide, a new substance with different properties than the original metal.'},
{id:'p103',difficulty:'easy',type:'concept',tag:'Concept',q:'Which of these is a pure substance?',choices:['Orange juice','Stainless steel','Carbon dioxide gas','Muddy water'],correct:2,solution:'CO2 has a fixed chemical formula and definite properties — a pure compound. Orange juice, stainless steel, and muddy water are all mixtures with variable composition.'},
{id:'p104',difficulty:'easy',type:'concept',tag:'Changes',q:'Sublimation of dry ice (solid CO2 turning directly into gas) is:',choices:['A chemical change because a gas forms','A physical change because the CO2 stays CO2 throughout','A nuclear change','Not a change at all'],correct:1,solution:'Sublimation is a phase change (solid → gas) — the substance is still CO2 before and after, just in a different physical state. No new substance forms, so it is a physical change.'},
{id:'p105',difficulty:'easy',type:'concept',tag:'Concept',q:'A homogeneous mixture is also called a:',choices:['Compound','Solution','Element','Suspension'],correct:1,solution:'A homogeneous mixture — one with uniform composition throughout — is also called a solution, whether it is a solid, liquid, or gas.'},
{id:'p106',difficulty:'easy',type:'concept',tag:'Separation',q:'Which pair correctly matches a separation technique to what it separates?',choices:['Filtration — dissolved salt from water','Magnetism — iron from sand','Distillation — sand from water','Evaporation — oil from water'],correct:1,solution:'A magnet attracts and removes magnetic materials like iron from a non-magnetic solid like sand. Filtration cannot remove dissolved salt (it passes through with the water); distillation and evaporation are not suited to separating sand.'},

/* ── MEDIUM (25) ── */
{id:'p107',difficulty:'medium',type:'concept',tag:'States of Matter',q:'A sample of matter has an indefinite shape, takes the shape of its container, but has a fixed volume that resists compression. This best describes matter in which phase?',choices:['Solid','Liquid','Gas','Plasma'],correct:1,solution:'Liquids take the shape of their container (unlike solids) but have a fixed volume that strongly resists compression (unlike gases, which are highly compressible).'},
{id:'p108',difficulty:'medium',type:'concept',tag:'Concept',q:'Sea water is generally classified as a homogeneous mixture, but near the shore it may contain visible suspended sand and sediment. What does this show?',choices:['Classification can depend on what is actually present in the specific sample being observed','Sea water is always a compound','Homogeneous and heterogeneous mean the same thing','Classification never changes based on sample'],correct:0,solution:'The classification of a sample depends on what is actually present in it. Clear open-ocean sea water (dissolved salts only) is homogeneous; shoreline water with visible suspended sediment is heterogeneous, since the composition is no longer uniform.'},
{id:'p109',difficulty:'medium',type:'concept',tag:'Concept',q:'Which statement correctly distinguishes a mixture from a pure compound at the particle level?',choices:['A mixture has only one type of particle; a compound has several','Both always have a single, fixed melting point','A compound\'s particles are all identical bonded units in a fixed ratio; a mixture\'s particles vary in identity or ratio','Mixtures cannot be separated by any method'],correct:2,solution:'In a compound, every particle is the same bonded unit, made of different atom types in a fixed ratio. In a mixture, particles can vary — different molecules present in varying proportions, not chemically bonded to each other.'},
{id:'p110',difficulty:'medium',type:'multi',tag:'Multi-step',q:'A chemist heats a solid sample and it does not melt at a single sharp temperature but instead softens gradually over a 40°C range. What does this suggest, and why?',choices:['The sample is a pure element of high purity','The sample is likely a mixture, because pure substances melt at a single, sharp temperature','The sample underwent a nuclear change','The sample is definitely a compound with a fixed formula'],correct:1,solution:'Pure substances (elements and compounds) melt sharply at one definite temperature. A wide melting range is a classic sign of an impure sample or a mixture, because different components melt at different temperatures.'},
{id:'p111',difficulty:'medium',type:'concept',tag:'Changes',q:'Which of the following changes releases a new gas as clear evidence of a chemical reaction?',choices:['Ice cream melting on a hot day','An antacid tablet fizzing in water','Sugar dissolving in tea','Water boiling in a kettle'],correct:1,solution:'An antacid tablet reacting with water produces carbon dioxide gas bubbles — evidence that a new substance has formed. Melting, dissolving, and boiling are all physical changes with no new substance produced.'},
{id:'p112',difficulty:'medium',type:'calc',tag:'Formula Counting',q:'How many total atoms are in 1 formula unit of (NH4)3PO4?',answer:20,tolerance:0.01,solution:'(NH4)3 = 3 N + 12 H. Plus PO4 = 1 P + 4 O. Total = 3+12+1+4 = <strong>20 atoms</strong>.'},
{id:'p113',difficulty:'medium',type:'calc',tag:'Formula Counting',q:'How many oxygen atoms are in 3 formula units of K2Cr2O7?',answer:21,tolerance:0.01,solution:'One formula unit of K2Cr2O7 has 7 oxygen atoms. For 3 formula units: 3 × 7 = <strong>21 oxygen atoms</strong>.'},
{id:'p114',difficulty:'medium',type:'calc',tag:'Formula Counting',q:'How many total atoms are in 2 formula units of Ba(OH)2?',answer:10,tolerance:0.01,solution:'One formula unit: Ba(1) + O(2) + H(2) = 5 atoms. For 2 formula units: 2 × 5 = <strong>10 atoms</strong>.'},
{id:'p115',difficulty:'medium',type:'calc',tag:'Formula Counting',q:'How many nitrogen atoms are in 4 formula units of (NH4)2CO3?',answer:8,tolerance:0.01,solution:'One formula unit has 2 nitrogen atoms (from the two NH4 groups). For 4 formula units: 4 × 2 = <strong>8 nitrogen atoms</strong>.'},
{id:'p116',difficulty:'medium',type:'calc',tag:'Formula Counting',q:'How many total atoms are in 1 formula unit of KMnO4?',answer:6,tolerance:0.01,solution:'K(1) + Mn(1) + O(4) = <strong>6 atoms</strong> total.'},
{id:'p117',difficulty:'medium',type:'concept',tag:'Concept',q:'A shiny gray solid conducts electricity, is malleable, and has the chemical symbol Ni on the periodic table. This substance is best classified as:',choices:['A compound','An element','A heterogeneous mixture','An alloy'],correct:1,solution:'A single chemical symbol (Ni) means only one type of atom is present — an element. Conductivity and malleability are typical metallic properties, consistent with nickel metal.'},
{id:'p118',difficulty:'medium',type:'concept',tag:'Concept',q:'Brass is an alloy of copper and zinc. Which statement correctly explains why brass is a mixture and not a compound?',choices:['Brass has a fixed 1:1 ratio of Cu to Zn, like a chemical formula','The ratio of copper to zinc in brass can vary, and there is no fixed chemical formula for it','Brass cannot conduct electricity','Copper and zinc react chemically to form brass'],correct:1,solution:'Brass has no fixed chemical formula — its copper-to-zinc ratio can be adjusted to change its properties (color, hardness). Variable composition without chemical bonding between the components is the hallmark of a mixture.'},
{id:'p119',difficulty:'medium',type:'multi',tag:'Multi-step',q:'Two samples are tested: Sample X boils at exactly 100°C every single time it is tested. Sample Y boils anywhere between 95°C and 105°C depending on the batch tested. Which is most likely a pure substance, and why?',choices:['Sample X, because pure substances have a single, sharp boiling point','Sample Y, because mixtures always boil at higher temperatures','Both, because boiling point does not indicate purity','Sample Y, because a range shows more precise measurement'],correct:0,solution:'A single, reproducible boiling point (Sample X) is the signature of a pure substance. A boiling range that varies between batches (Sample Y) indicates the presence of a mixture with variable composition.'},
{id:'p120',difficulty:'medium',type:'concept',tag:'Concept',q:'Which of the following best explains why filtering salt water does NOT remove the dissolved salt?',choices:['Salt is too heavy to pass through filter paper','Dissolved salt ions are far smaller than the filter paper\'s pores and pass through along with the water','Filter paper only works on gases','Salt evaporates during filtration'],correct:1,solution:'Once dissolved, salt exists as individual ions dispersed throughout the water at a scale far smaller than filter paper\'s pores. Filtration only separates undissolved solids from a liquid, not dissolved solutes.'},
{id:'p121',difficulty:'medium',type:'concept',tag:'Concept',q:'A liquid mixture of oil and vinegar separates into two visible layers when left standing. This is evidence that the mixture is:',choices:['A compound','A homogeneous mixture','A heterogeneous mixture','A pure substance'],correct:2,solution:'Oil and vinegar do not mix uniformly — they form two distinct layers with different compositions, which is the definition of a heterogeneous mixture.'},
{id:'p122',difficulty:'medium',type:'multi',tag:'Multi-step',q:'A student burns a piece of magnesium ribbon in air. It produces a bright white light and leaves behind a white powder that is heavier than the original ribbon. What evidence indicates a chemical change occurred, and why did the mass increase?',choices:['Light release only; the mass increase was measurement error','Light release and a new substance (white powder) formed; the mass increased because oxygen from the air combined chemically with the magnesium','No chemical change occurred, since magnesium is an element','Mass increased due to a physical change that absorbed water vapor'],correct:1,solution:'The bright light and the appearance of a new substance (magnesium oxide, a white powder) are both signs of a chemical change. The mass increases because oxygen atoms from the air have bonded with the magnesium, adding their mass to the solid product.'},
{id:'p123',difficulty:'medium',type:'concept',tag:'Concept',q:'Which statement about isotopes of the same element (like carbon-12 and carbon-14) is correct?',choices:['They are different elements because they have different masses','They are the same element because they have the same number of protons','They are a compound because they have different numbers of neutrons','They are a mixture of two elements'],correct:1,solution:'An element is defined by its number of protons, not its mass. Carbon-12 and carbon-14 both have 6 protons — they are both carbon, just with different numbers of neutrons (isotopes), not different elements or a compound.'},
{id:'p124',difficulty:'medium',type:'concept',tag:'Concept',q:'A gas mixture is compressed into a cylinder. Even under high pressure, the different gas molecules remain uniformly spread throughout the container. This mixture is:',choices:['Heterogeneous, because it is under pressure','Homogeneous, because the composition is uniform throughout','A compound, because gases are always compounds','Not classifiable'],correct:1,solution:'Pressure does not determine homogeneity — uniform composition does. Since the different gas molecules remain evenly distributed throughout, this is a homogeneous mixture.'},
{id:'p125',difficulty:'medium',type:'concept',tag:'Concept',q:'Which of the following would you expect to have a fixed chemical formula, rather than a variable composition?',choices:['Granite','Air','Sucrose (table sugar)','Trail mix'],correct:2,solution:'Sucrose is a pure compound (C12H22O11) with a fixed, exact formula. Granite, air, and trail mix are all mixtures whose exact composition can vary from sample to sample.'},
{id:'p126',difficulty:'medium',type:'multi',tag:'Multi-step',q:'A student compares two colorless liquids. Liquid 1 conducts electricity strongly. Liquid 2 does not conduct electricity at all. Both boil at exactly 100°C. What can the student conclude?',choices:['Both liquids must be pure water','Liquid 1 likely contains dissolved ions (like salt water); Liquid 2 is likely pure water','Conductivity has no relationship to a liquid\'s composition','Liquid 2 must be a heterogeneous mixture'],correct:1,solution:'Pure water does not conduct electricity well, but dissolved ionic compounds (like NaCl) create a solution that does conduct. Liquid 1\'s conductivity suggests dissolved ions are present; Liquid 2\'s lack of conductivity is consistent with pure water.'},
{id:'p127',difficulty:'medium',type:'concept',tag:'Properties',q:'Which pair of properties would best help identify an unknown pure substance, regardless of how much of it you have?',choices:['Mass and volume','Melting point and density','Length and width','Number of atoms and total mass'],correct:1,solution:'Melting point and density are both intensive properties — they stay the same no matter the sample size, making them reliable for identification. Mass, volume, length, and atom count all change with sample size.'},
{id:'p128',difficulty:'medium',type:'concept',tag:'Separation',q:'A sugar-water solution is heated until all the water evaporates, leaving solid sugar behind. Which property of water made this separation possible?',choices:['Its color','Its boiling point (volatility)','Its magnetism','Its density alone'],correct:1,solution:'Water is far more volatile (lower boiling point) than solid sugar, so heating drives off the water as vapor while the sugar, which does not vaporize under these conditions, is left behind.'},
{id:'p129',difficulty:'medium',type:'calc',tag:'Formula Counting',q:'How many total atoms are in 3 formula units of (NH4)2SO4?',answer:45,tolerance:0.01,solution:'One formula unit has 2 N + 8 H + 1 S + 4 O = 15 atoms. For 3 formula units: 3 × 15 = <strong>45 atoms</strong>.'},
{id:'p130',difficulty:'medium',type:'concept',tag:'Concept',q:'Which of the following statements about mixtures is TRUE?',choices:['Mixtures always have a fixed ratio of components','Mixtures can only be separated using chemical reactions','The properties of any mixture are identical throughout, no matter what type it is','Mixtures can be separated by physical methods because no new chemical bonds form between the components'],correct:3,solution:'Because mixtures are only physically combined (no chemical bonds between different components), they can always be separated using physical methods like filtration, evaporation, distillation, or magnetism.'},
{id:'p131',difficulty:'medium',type:'multi',tag:'Multi-step',q:'A student is given an unlabeled clear liquid. It does not boil at a single fixed temperature, and evaporating a small sample leaves behind a solid residue. What can the student conclude about the liquid?',choices:['It is a pure element','It is a compound with a fixed formula','It is likely a mixture (a solution) — the boiling range and leftover residue both point to more than one component being present','It cannot be classified without further tests'],correct:2,solution:'A varying boiling point rules out a pure substance. The solid residue after evaporation confirms a dissolved, non-volatile component was present. Together, these point to the liquid being a solution — a homogeneous mixture.'},

/* ── HARD (15) ── */
{id:'p132',difficulty:'hard',type:'multi',tag:'Multi-step',q:'Four sealed containers are compared at the same temperature and pressure. Container A holds only Ne atoms. Container B holds N2 and O2 molecules mixed uniformly. Container C holds only NO2 molecules (each with 1 N bonded to 2 O). Container D holds liquid water with visible chunks of ice floating in it. Which classification set is correct for all four?',choices:['A = element, B = homogeneous mixture, C = compound, D = heterogeneous mixture','A = compound, B = element, C = mixture, D = homogeneous mixture','A = element, B = compound, C = mixture, D = compound','A = mixture, B = compound, C = element, D = heterogeneous mixture'],correct:0,solution:'A: single unbonded atom type = element. B: two different molecules uniformly mixed, not bonded = homogeneous mixture. C: two atom types bonded in a fixed ratio = compound. D: liquid water plus solid ice is two visibly different physical regions of the same substance, which counts as heterogeneous (non-uniform) even though both are H2O.'},
{id:'p133',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A student is given four unlabeled white solids and must identify which are pure compounds using only a melting point apparatus and a magnifying glass. Solid 1 melts sharply at 801°C. Solid 2 melts over a range from 150–210°C and shows two distinct colors of crystal under magnification. Solid 3 melts sharply at 1538°C and conducts electricity as a solid. Solid 4 melts sharply at 993°C and shows uniform white crystals under magnification. Which solids are most likely pure substances?',choices:['Only Solid 1','Solids 1 and 4 — both have sharp melting points and uniform appearance','All four solids','Only Solid 2'],correct:1,solution:'Solids 1 and 4 both melt sharply (single temperature) and show uniform crystal appearance — both signs of purity. Solid 2\'s wide melting range and two visible crystal colors indicate a mixture. Solid 3\'s sharp melting point and conductivity actually suggest a pure metallic element, but it wasn\'t confirmed as uniform under the magnifying glass in this scenario, so only 1 and 4 have both lines of evidence.'},
{id:'p134',difficulty:'hard',type:'concept',tag:'Concept',q:'A sample of "pure" bottled water actually contains trace dissolved minerals (calcium and magnesium ions) at very low concentration, uniformly dissolved throughout. Strictly speaking, how should this bottled water be classified, and why?',choices:['As a compound, because it is mostly H2O','As a pure substance, because the minerals cannot be tasted','As a homogeneous mixture, because it contains more than one substance uniformly dissolved, even at low concentration','As a heterogeneous mixture, because minerals are solids'],correct:2,solution:'Strict chemical classification does not depend on concentration or taste — any sample containing more than one substance, even in trace amounts, is technically a mixture. Since the minerals are uniformly dissolved, it is a homogeneous mixture, not a pure substance.'},
{id:'p135',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A student examines an unknown gray metallic-looking sample. Tests show: (1) it does not have a single sharp melting point but softens over a range, (2) a magnet attracts part of the sample but not all of it, (3) under a microscope, two differently colored particle types are visible. Based on all three observations together, what is the best classification?',choices:['A pure element, because it is metallic','A compound, because it conducts electricity','A heterogeneous mixture — the melting range, partial magnetism, and visibly different particles all point to more than one component that is not uniformly distributed','A homogeneous mixture, because it looks uniform to the naked eye'],correct:2,solution:'All three pieces of evidence point the same direction: a melting range (not a sharp point), only partial magnetic attraction (some components respond, others don\'t), and visibly distinct particle types under magnification. Together, these rule out a pure substance and rule out uniform distribution — a heterogeneous mixture.'},
{id:'p136',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A beaker contains sand, salt, and small iron nails all mixed together. A separate flask holds ethanol and water mixed as one clear liquid. What is the full correct sequence of physical methods to obtain all four pure substances (sand, salt, iron, and separately ethanol and water)?',choices:['Magnet removes iron (magnetism) → add water, filter (separates sand, using insolubility) → evaporate the filtrate (recovers salt, using volatility) → distill the ethanol-water mixture separately (separates by boiling point)','Filter everything first, then evaporate, then use a magnet, then distill','Distill the solid mixture first, then filter, then use a magnet','Evaporate the solid mixture, then filter, then distill, then use a magnet'],correct:0,solution:'Each step targets one property in the right order: magnetism removes iron first (it would interfere with later steps); adding water dissolves the salt so filtration removes the sand; evaporating the filtrate recovers the salt; the separate ethanol-water solution requires distillation, exploiting their different boiling points.'},
{id:'p137',difficulty:'hard',type:'concept',tag:'Concept',q:'Hydrated copper sulfate, CuSO4·5H2O, contains water molecules built directly into its crystal structure in a fixed ratio. Is this substance a compound or a mixture, and why?',choices:['A mixture, because it contains water plus copper sulfate as two separate ingredients','A compound, because the water molecules are incorporated in a fixed, definite ratio (5 per formula unit) as part of the crystal\'s structure','Neither — hydrates cannot be classified','A heterogeneous mixture, because the water can be seen separately'],correct:1,solution:'Even though a hydrate contains water, that water is chemically incorporated into the crystal lattice in an exact, fixed ratio (5 H2O per formula unit here). A fixed, reproducible ratio is the signature of a compound, not a mixture.'},
{id:'p138',difficulty:'hard',type:'calc',tag:'Formula Counting',q:'How many total atoms are in 2 formula units of CuSO4·5H2O?',answer:42,tolerance:0.5,solution:'One formula unit: Cu(1) + S(1) + O(4, from sulfate) + 5×H2O (10 H + 5 O) → O total = 4+5=9, H=10. Sum = 1+1+9+10 = 21 atoms. For 2 formula units: 2 × 21 = <strong>42 atoms</strong>.'},
{id:'p139',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A student claims: "Since salt water and sugar water are both homogeneous mixtures, they must have identical properties, like the same boiling point." Evaluate this claim.',choices:['The claim is correct; all homogeneous mixtures share identical boiling points','The claim is false — properties like boiling point depend on the specific solute and its concentration, not simply on being classified as "homogeneous"','The claim is correct only for solids dissolved in water','Homogeneous mixtures can never have a different boiling point than the pure solvent'],correct:1,solution:'"Homogeneous" only describes how uniformly a mixture is distributed — it says nothing about which specific properties result. Different solutes, at different concentrations, raise the boiling point of water by different amounts (a colligative property), so salt water and sugar water will generally boil at different temperatures.'},
{id:'p140',difficulty:'hard',type:'concept',tag:'Changes',q:'Steel wool burns in pure oxygen, producing bright light, heat, and a fragile black/gray residue that is heavier than the original steel wool. A student claims this must be a physical change because "the iron atoms are all still there." Evaluate this reasoning.',choices:['The student is correct because no atoms were destroyed','The student is incorrect — even though the atoms are conserved, they have chemically bonded with oxygen to form a new substance (iron oxide) with entirely different properties, making this a chemical change','The student is correct because the mass increased','This is a nuclear change, not physical or chemical'],correct:1,solution:'Conservation of atoms is true of every chemical change too — atoms are never destroyed, only rearranged into new bonds. The iron atoms combined with oxygen atoms to form a new compound (iron oxide) with different properties than either starting material, which is exactly what defines a chemical change.'},
{id:'p141',difficulty:'hard',type:'multi',tag:'Multi-step',q:'Four processes are listed: (1) natural gas burning on a stove, (2) dry ice subliming at room temperature, (3) a copper wire being drawn out into thin wire, (4) yeast fermenting sugar into carbon dioxide and alcohol. A student claims processes 1 and 4 are chemical changes, while 2 and 3 are physical changes. Evaluate this claim.',choices:['The claim is entirely correct — 1 and 4 form new substances; 2 and 3 do not','The claim is incorrect; all four are chemical changes','The claim is incorrect; all four are physical changes','Only process 1 is a chemical change'],correct:0,solution:'Burning natural gas (1) produces CO2 and H2O — new substances, a chemical change. Fermentation (4) converts sugar into alcohol and CO2 — new substances, chemical change. Dry ice subliming (2) is CO2 changing state only. Drawing copper wire (3) reshapes copper without changing its identity. The claim correctly separates all four.'},
{id:'p142',difficulty:'hard',type:'calc',tag:'Formula Counting',q:'How many total atoms are in 3 formula units of Al2(Cr2O7)3?',answer:87,tolerance:1,solution:'One formula unit: Al(2) + (Cr2O7)3 = Cr(2×3=6) + O(7×3=21). Total = 2+6+21 = 29 atoms. For 3 formula units: 3 × 29 = <strong>87 atoms</strong>.'},
{id:'p143',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A solid sample under a microscope shows a uniform, single crystal structure with carbon and hydrogen in a precise 1:4 ratio (formula CH4, frozen solid). A separate sample of solidified "dry air" shows visibly separate crystal domains of different substances under the microscope. Compare and classify both samples.',choices:['Both are compounds because they are solids','Solid CH4 is a compound (fixed 1:4 ratio, uniform structure); solidified air is a heterogeneous mixture (visibly separate domains of different substances)','Solid CH4 is a mixture; solidified air is a compound','Both are heterogeneous mixtures because they are both solids'],correct:1,solution:'Being solid does not determine classification — composition does. CH4 has a fixed atomic ratio in every particle, so it is a compound. Solidified air still contains visibly separate domains of different gases that froze out individually, so it remains a (now solid) heterogeneous mixture.'},
{id:'p144',difficulty:'hard',type:'concept',tag:'Concept',q:'A student argues that because vinegar (a solution of acetic acid in water) can be separated by distillation, vinegar must be a compound, since "you need a method involving heat to separate it." What is the flaw in this reasoning?',choices:['The reasoning is correct — needing heat always indicates a compound','The flaw is that distillation is a physical separation method (based on differing boiling points), not a chemical one — needing heat to separate something does not make it a compound','The flaw is that vinegar cannot actually be distilled','The reasoning is correct because acetic acid reacts with water'],correct:1,solution:'Requiring heat or a specific technique does not by itself indicate a chemical process. Distillation only exploits physical boiling-point differences and does not break or form chemical bonds — it is a physical separation, fully consistent with vinegar being a mixture (a solution).'},
{id:'p145',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A geologist collects a rock sample containing visibly distinct bands of quartz, mica, and feldspar. A chemist separately prepares a solid alloy of gold and silver ("white gold") where the two metals are uniformly and indistinguishably blended, even under a microscope. Compare and correctly classify both.',choices:['Both are compounds','Both are heterogeneous mixtures','The rock is a heterogeneous mixture (visibly distinct regions); the white gold alloy is a homogeneous mixture (uniformly blended, with no fixed ratio required)','The rock is homogeneous; the alloy is heterogeneous'],correct:2,solution:'The rock has visibly separate mineral bands — non-uniform composition, heterogeneous. The alloy is blended so thoroughly that no distinct regions are visible even under magnification, and its composition can be varied without a fixed formula — a homogeneous mixture.'},
{id:'p146',difficulty:'hard',type:'calc',tag:'Formula Counting',q:'A hydrate of magnesium sulfate has the formula MgSO4·7H2O (Epsom salt). How many total atoms are in 4 formula units?',answer:108,tolerance:1,solution:'One formula unit: Mg(1) + S(1) + O(4, from sulfate) + 7×H2O (14 H + 7 O) → O total = 4+7=11, H=14. Sum = 1+1+11+14 = 27 atoms. For 4 formula units: 4 × 27 = <strong>108 atoms</strong>.'},

/* ══════════════ HARD EXPANSION BATCH — 30 additional hard problems ══════════════ */
{id:'p147',difficulty:'hard',type:'calc',tag:'Formula Counting',q:'How many total atoms are in 6 formula units of Ca3(PO4)2?',answer:78,tolerance:1,solution:'One formula unit: Ca(3) + (PO4)2 = P(2) + O(4×2=8). Total = 3+2+8 = 13 atoms. For 6 formula units: 6 × 13 = <strong>78 atoms</strong>.'},
{id:'p148',difficulty:'hard',type:'calc',tag:'Formula Counting',q:'How many oxygen atoms are in 4 formula units of Fe2(SO4)3?',answer:48,tolerance:1,solution:'One formula unit of Fe2(SO4)3 has 3 sulfate groups, each with 4 oxygens: 3 × 4 = 12 oxygen atoms. For 4 formula units: 4 × 12 = <strong>48 oxygen atoms</strong>.'},
{id:'p149',difficulty:'hard',type:'calc',tag:'Formula Counting',q:'How many total atoms are in 3 formula units of (NH4)2Cr2O7?',answer:57,tolerance:1,solution:'One formula unit: (NH4)2 = 2 N + 8 H, Cr2O7 = 2 Cr + 7 O. Total = 2+8+2+7 = 19 atoms. For 3 formula units: 3 × 19 = <strong>57 atoms</strong>.'},
{id:'p150',difficulty:'hard',type:'multi',tag:'Multi-step',q:'Classify these five samples using logic alone: (1) a substance with formula C6H12O6 that dissolves completely in water leaving no residue; (2) muddy pond water; (3) a metal alloy sold as "14-karat gold" (58.3% gold, uniform color throughout, no fixed formula); (4) a sealed can of soda showing visible bubbles of gas rising through the liquid when opened; (5) a block of pure aluminum. Which classification set is fully correct?',choices:['1 = compound, 2 = heterogeneous mixture, 3 = homogeneous mixture, 4 = heterogeneous (visible gas + liquid phases), 5 = element','1 = mixture, 2 = homogeneous mixture, 3 = compound, 4 = element, 5 = mixture','1 = compound, 2 = compound, 3 = element, 4 = mixture, 5 = compound','1 = element, 2 = heterogeneous mixture, 3 = compound, 4 = homogeneous mixture, 5 = mixture'],correct:0,solution:'(1) A fixed formula that dissolves cleanly = compound. (2) Visible suspended particles = heterogeneous mixture. (3) Variable composition, uniformly blended = homogeneous mixture (alloy). (4) While gas bubbles are visibly rising through the liquid, two distinct phases (gas + liquid) are present at once — heterogeneous. (5) One chemical symbol = element.'},
{id:'p151',difficulty:'hard',type:'concept',tag:'Concept',q:'"18-karat gold" jewelry is 75% gold, with the rest a uniform blend of other metals like copper and silver. Even though it\'s called "gold," why is it NOT classified as the pure element gold?',choices:['Because gold jewelry is always fake','Because it contains other metals uniformly blended with the gold, making it an alloy (a homogeneous mixture), not pure gold','Because 18-karat gold has a chemical formula different from Au','Because its color looks different from pure gold'],correct:1,solution:'A commercial name doesn\'t determine chemical classification. Because 18-karat gold is a blend of multiple metals with no fixed atomic ratio, it is an alloy — a homogeneous mixture — not the pure element gold (Au), even though gold is its main component.'},
{id:'p152',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A researcher discovers a new mineral. Tests show: it melts sharply at 612°C; it has a fixed ratio of 2 sodium atoms to 1 sulfur atom to 4 oxygen atoms in every sample regardless of source; and it cannot be broken into simpler substances by filtration, magnetism, or evaporation — but CAN be broken apart by passing electricity through its molten form (electrolysis). What does this tell us about the mineral?',choices:['It is a mixture, because it can be broken apart at all','It is a compound — the fixed elemental ratio and sharp melting point indicate a pure substance, and needing a chemical process (electrolysis) rather than physical separation confirms it is chemically bonded, not just mixed','It is an element, because it has a sharp melting point','It cannot be classified with this information'],correct:1,solution:'A fixed atomic ratio across every sample and a sharp melting point both indicate a pure substance. That it resists all physical separation methods but yields to electrolysis (a chemical process that breaks chemical bonds) confirms its atoms are chemically bonded — a compound, not a mixture.'},
{id:'p153',difficulty:'hard',type:'calc',tag:'Formula Counting',q:'How many total atoms are in 2 formula units of Al2(SO4)3·18H2O?',answer:142,tolerance:2,solution:'One formula unit: Al2(SO4)3 = Al(2) + S(3) + O(12), plus 18×H2O = 36 H + 18 O. Total O = 12+18=30, H=36. Sum = 2+3+30+36 = 71 atoms. For 2 formula units: 2 × 71 = <strong>142 atoms</strong>.'},
{id:'p154',difficulty:'hard',type:'multi',tag:'Separation',q:'A mixture of iodine crystals and sand is heated gently. The iodine sublimes (turns directly from solid to purple vapor) and recondenses as pure iodine crystals on a cool surface, leaving the sand behind. What separation technique is this, and what property does it depend on?',choices:['Filtration; depends on particle size','Sublimation; depends on iodine\'s ability to pass directly from solid to gas at a lower temperature than sand requires to melt or vaporize','Distillation; depends on the boiling point of a liquid','Chromatography; depends on solubility in a solvent'],correct:1,solution:'This is sublimation — a physical separation technique that works because iodine converts directly from solid to gas at a relatively low temperature, while sand does not sublime under these conditions at all. Cooling the vapor recondenses pure solid iodine, leaving the sand untouched.'},
{id:'p155',difficulty:'hard',type:'concept',tag:'Concept',q:'A student says: "Water is always a compound, so any sample of water must be pure." What is wrong with this statement?',choices:['The statement is fully correct','Water (H2O) is indeed always a compound by its chemical identity, but a specific sample of water (like tap water or seawater) can still be impure — dissolved substances mixed into it make that sample a mixture, even though H2O itself remains a compound','Water is not a compound at all','Pure water cannot exist anywhere in nature'],correct:1,solution:'This distinguishes the identity of a substance from the purity of a particular sample. H2O as a chemical species is always a compound. But a sample labeled "water" — tap water, seawater, pond water — usually has other substances dissolved in it, making that specific sample a mixture.'},
{id:'p156',difficulty:'hard',type:'calc',tag:'Formula Counting',q:'How many total atoms are in 3 formula units of K4Fe(CN)6?',answer:51,tolerance:1,solution:'One formula unit: K(4) + Fe(1) + (CN)6 = 6 C + 6 N. Total = 4+1+6+6 = 17 atoms. For 3 formula units: 3 × 17 = <strong>51 atoms</strong>.'},
{id:'p157',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A solid mixture contains NaCl (soluble in water), CaCO3 (insoluble in water, but dissolves when reacted with dilute HCl), and sand (insoluble in both water and HCl). Design a sequence to separate all three into pure components.',choices:['Add water, filter (separates dissolved NaCl solution from insoluble CaCO3 + sand); evaporate the filtrate to recover NaCl; add HCl to the remaining solid and filter again (CaCO3 reacts and dissolves, sand remains as residue); recover the sand from the filter','Add HCl to the whole mixture first to dissolve everything, then filter','Evaporate the whole mixture first, then add water','Use a magnet to remove the sand'],correct:0,solution:'Each reagent targets one component: water dissolves only the NaCl, so filtering isolates it from the two insoluble solids; evaporating that filtrate recovers solid NaCl. Adding HCl to the remaining solid dissolves the CaCO3 (via reaction) but not the sand, so a second filtration isolates the sand as the final residue.'},
{id:'p158',difficulty:'hard',type:'concept',tag:'Concept',q:'Which of the following, if true, would be the STRONGEST evidence that an unknown clear liquid is a pure compound rather than a solution?',choices:['It is colorless','It has a single, precise, reproducible boiling point at a given pressure, confirmed across multiple independently prepared samples','It does not conduct electricity','It has a pleasant smell'],correct:1,solution:'A single, sharp, reproducible boiling point — confirmed across multiple independently made samples — is the strongest and most diagnostic evidence of purity. Color, conductivity, and smell can all vary for reasons unrelated to purity.'},
{id:'p159',difficulty:'hard',type:'multi',tag:'Multi-step',q:'Three unlabeled gas samples are described at the particle level, all at the same temperature and pressure. Gas X: identical three-atom bent molecules throughout. Gas Y: a mix of two different types of diatomic molecules, uniformly interspersed. Gas Z: single, identical, unbonded atoms only. Which statement correctly matches each gas to a classification with a real example?',choices:['X = compound (like H2O vapor); Y = homogeneous mixture (like a blend of O2 and N2); Z = element (like Ne)','X = element; Y = compound; Z = mixture','X = mixture; Y = element; Z = compound','X = compound; Y = compound; Z = mixture'],correct:0,solution:'X: identical bent 3-atom molecules with two atom types bonded in a fixed ratio = compound (H2O). Y: two different molecule types uniformly mixed, not bonded to each other = homogeneous mixture (like air\'s O2/N2 blend). Z: single unbonded atom type = element (like Ne).'},
{id:'p160',difficulty:'hard',type:'calc',tag:'Formula Counting',q:'How many total atoms are in 4 formula units of Ba3(PO4)2?',answer:52,tolerance:1,solution:'One formula unit: Ba(3) + (PO4)2 = P(2) + O(8). Total = 3+2+8 = 13 atoms. For 4 formula units: 4 × 13 = <strong>52 atoms</strong>.'},
{id:'p161',difficulty:'hard',type:'concept',tag:'Concept',q:'A student proposes: "Since both salt (NaCl) and sugar (C12H22O11) dissolve completely and invisibly in water, both solutions must be identical in classification and behavior." Which part of this claim is correct, and which part needs more nuance?',choices:['Both parts are fully correct','Both solutions are correctly classified as homogeneous mixtures (that part is correct), but they are NOT identical in behavior — for example, salt water conducts electricity because it contains dissolved ions, while sugar water does not, since sugar dissolves as neutral molecules','Neither solution is a homogeneous mixture','Salt water is a compound while sugar water is a mixture'],correct:1,solution:'Classification (homogeneous mixture) is correct for both. But classification alone doesn\'t predict every property. NaCl dissociates into charged ions in water, allowing the solution to conduct electricity; sugar dissolves as whole, neutral molecules, so sugar water does not conduct.'},
{id:'p162',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A quality-control chemist tests three batches of a "pure" pharmaceutical compound. Batch 1 melts sharply at 156°C. Batch 2 melts over a range of 148–156°C. Batch 3 melts sharply at 156°C in one test, but a different sample from the same production run melts at 152°C. Rank the batches from purest to least pure and explain.',choices:['Batch 2 is purest because its melting range includes 156°C','Batch 1 is purest (sharp, single melting point); Batch 2 is least pure (widest melting range, indicating the most impurity); Batch 3 is intermediate (sharp points individually, but inconsistent between samples, suggesting non-uniform contamination)','All three batches are equally pure since they are all near 156°C','Batch 3 is purest because it gave two different results'],correct:1,solution:'Batch 1\'s single sharp melting point at exactly 156°C is the clearest sign of high purity. Batch 2\'s wide melting range signals significant impurity. Batch 3\'s inconsistency between samples — sharp individually, but different between samples — suggests the impurity is not evenly distributed throughout the batch.'},
{id:'p163',difficulty:'hard',type:'calc',tag:'Formula Counting',q:'How many total atoms are in 2 formula units of Mg(HCO3)2?',answer:22,tolerance:0.5,solution:'One formula unit: Mg(1) + (HCO3)2 = 2 H + 2 C + 6 O. Total = 1+2+2+6 = 11 atoms. For 2 formula units: 2 × 11 = <strong>22 atoms</strong>.'},
{id:'p164',difficulty:'hard',type:'concept',tag:'Concept',q:'Sea salt harvested by evaporating seawater in shallow ponds still contains trace amounts of other minerals (like magnesium and potassium salts), even though it is sold as "pure sea salt." Why does this happen, and what does "pure" mean here compared to the strict chemistry definition?',choices:['Evaporation always produces perfectly pure NaCl with zero exceptions','Evaporation concentrates all the dissolved solids in seawater (not just NaCl), since it only removes water; commercially "pure" sea salt is really a mixture dominated by NaCl but still containing other dissolved minerals, unlike chemically pure NaCl','Sea salt becomes a single new compound made of all the minerals combined','The minerals form a new element during evaporation'],correct:1,solution:'Evaporation removes only water — it does not sort out which dissolved solid is which. All the dissolved minerals in seawater are left behind together, so "sea salt" is really a mixture that is mostly NaCl, not chemically pure sodium chloride.'},
{id:'p165',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A metallurgist compares two samples: Sample A is a bar of pure titanium (Ti) metal. Sample B is a titanium alloy used in aircraft, containing titanium uniformly blended with aluminum and vanadium at the atomic scale, with no fixed ratio required by any single chemical formula. Which statement correctly compares their classification and explains a key practical difference?',choices:['Both are elements since both are metals','Sample A is an element (only Ti atoms); Sample B is a homogeneous mixture (alloy) — because it lacks a fixed chemical ratio, its exact composition can be adjusted to fine-tune strength and weight for aerospace use','Sample A is a mixture; Sample B is a compound','Both are compounds because they are both man-made'],correct:1,solution:'Sample A has only one atom type — an element. Sample B is uniformly blended but has no fixed formula, so it is a homogeneous mixture (an alloy). Because alloys are mixtures, engineers can adjust the exact proportions to optimize properties like strength-to-weight ratio, something impossible with a fixed-formula compound.'},
{id:'p166',difficulty:'hard',type:'calc',tag:'Formula Counting',q:'How many total atoms are in 3 formula units of (NH4)2HPO4?',answer:48,tolerance:1,solution:'One formula unit: (NH4)2 = 2 N + 8 H, plus the acidic H = 1 H, plus PO4 = 1 P + 4 O. Totals: N=2, H=8+1=9, P=1, O=4. Sum = 2+9+1+4 = 16 atoms. For 3 formula units: 3 × 16 = <strong>48 atoms</strong>.'},
{id:'p167',difficulty:'hard',type:'concept',tag:'Properties',q:'Which of the following best illustrates the difference between an intensive property useful for identification and an extensive property that is NOT useful for identification?',choices:['Using density (intensive — the same regardless of sample size) to identify an unknown metal, rather than mass (extensive — changes with sample size)','Using mass to identify a metal because heavier samples are always purer','Using volume, because larger samples are easier to measure','Using both equally, since they give the same information'],correct:0,solution:'Density is intensive — a gold nugget and a gold bar have the same density even though their masses differ hugely. That makes density (not mass, which is extensive and scales with sample size) the reliable tool for identifying an unknown material.'},
{id:'p168',difficulty:'hard',type:'multi',tag:'Multi-step',q:'An unknown white powder is insoluble in cold water but dissolves completely and rapidly when the water is heated to boiling, then recrystallizes as identical, uniform crystals as the hot solution cools. What does this behavior suggest, and what technique does it describe?',choices:['The powder is a heterogeneous mixture and no real separation is happening','This describes recrystallization — a physical purification technique that works because the powder\'s solubility changes with temperature; the uniform crystals forming on cooling support that the powder is a pure compound','The powder underwent a chemical change when heated','The powder is a gas at room temperature'],correct:1,solution:'Recrystallization exploits solubility that increases with temperature: heating dissolves more solid, then cooling forces it back out as crystals, purifying the sample as impurities tend to stay dissolved. Forming identical, uniform crystals is further evidence the recovered solid is a pure compound.'},
{id:'p169',difficulty:'hard',type:'calc',tag:'Formula Counting',q:'How many total atoms are in 2 formula units of (NH4)2Fe(SO4)2·6H2O?',answer:78,tolerance:2,solution:'One formula unit: (NH4)2 = 2 N + 8 H, Fe = 1, (SO4)2 = 2 S + 8 O, 6 H2O = 12 H + 6 O. Totals: N=2, H=8+12=20, Fe=1, S=2, O=8+6=14. Sum = 2+20+1+2+14 = 39 atoms. For 2 formula units: 2 × 39 = <strong>78 atoms</strong>.'},
{id:'p170',difficulty:'hard',type:'multi',tag:'Multi-step',q:'Three sealed opaque containers of identical volume, at the same temperature and pressure, each hold a different pure colorless gas: helium (He, molar mass ≈ 4 g/mol), nitrogen (N2, ≈ 28 g/mol), or carbon dioxide (CO2, ≈ 44 g/mol). Weighing shows Container 1 is heaviest, Container 2 is lightest, and Container 3 is in between. Which container holds which gas?',choices:['Container 1 = CO2 (heaviest), Container 2 = He (lightest), Container 3 = N2 (middle)','Container 1 = He, Container 2 = CO2, Container 3 = N2','All containers hold the same gas since they have the same volume','Container 1 = N2, Container 2 = CO2, Container 3 = He'],correct:0,solution:'At equal volume, temperature, and pressure, equal numbers of gas particles are present in each container, so the total mass ranks in the same order as molar mass: CO2 (44) is heaviest, He (4) is lightest, N2 (28) is in between.'},
{id:'p171',difficulty:'hard',type:'concept',tag:'Concept',q:'Smoke from a campfire is produced by a chemical change happening right in front of you, but once formed, the smoke itself is best classified as what type of matter?',choices:['A pure compound, because it came from a chemical reaction','A heterogeneous mixture — smoke is tiny solid/liquid particles (ash, soot, unburned fuel droplets) suspended in a mixture of gases, visibly non-uniform up close','An element, because it is a gas','A homogeneous mixture, because it looks like a uniform gray cloud from a distance'],correct:1,solution:'How smoke forms (a chemical change) is a separate question from what smoke is once it exists. Smoke is made of many different substances — soot, ash particles, water vapor, unburned fuel droplets, and various gases — none uniformly distributed at the particle level, making it a heterogeneous mixture.'},
{id:'p172',difficulty:'hard',type:'calc',tag:'Formula Counting',q:'How many total atoms are in 4 formula units of Cr2(SO4)3?',answer:68,tolerance:1,solution:'One formula unit: Cr(2) + (SO4)3 = 3 S + 12 O. Total = 2+3+12 = 17 atoms. For 4 formula units: 4 × 17 = <strong>68 atoms</strong>.'},
{id:'p173',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A forensic chemist analyzes an unknown white crystalline solid. It melts sharply at 186°C, is soluble in water, and elemental analysis shows a fixed 1:1 mole ratio of sodium to a polyatomic ion, giving the same formula NaC2H3O2 across every independent sample tested. What classification is best supported, and what is the strongest evidence?',choices:['Mixture; the strongest evidence is that it dissolves in water','Compound; the strongest evidence is the fixed, reproducible chemical formula (NaC2H3O2) across independent samples, combined with a sharp melting point','Element; because it has a chemical formula','This cannot be determined without a mass spectrometer'],correct:1,solution:'A fixed formula that is reproducible across independently tested samples is the strongest possible evidence of a compound — it shows the atoms combine in a definite, unchanging ratio no matter the source. The sharp melting point independently supports the same conclusion.'},
{id:'p174',difficulty:'hard',type:'concept',tag:'Changes',q:'Which of the following correctly identifies AND corrects a common misconception about physical vs. chemical changes?',choices:['"Chemical changes always involve fire" — correction: many chemical changes (like rusting or digestion) occur without any flame or visible heat','"Physical changes are always reversible" — correction: this is actually true in every single case','"Chemical changes always produce a gas" — correction: this is always true','"Physical changes never involve energy changes" — correction: this is always true'],correct:0,solution:'Fire and flame are not required for a chemical change — rusting, digestion, and many other reactions happen slowly, without any visible flame, yet still form new substances. The other three options each pair a false statement with an equally false "correction," so they don\'t actually correct anything.'},
{id:'p175',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A teacher shows two clear, colorless solutions and asks which is "pure water" and which is "salt water," without tasting or testing conductivity. A student suggests density: pure water is 1.00 g/mL at 4°C, while salt water is denser due to dissolved NaCl. Measuring 50.0 mL of each: Solution A has a mass of 50.0 g; Solution B has a mass of 51.8 g. Which is pure water, and what does this method rely on?',choices:['Solution A is pure water (density 1.00 g/mL, matching the known value); Solution B is salt water (higher density from dissolved solute); this method relies on density as an intensive, identifying physical property','Solution B is pure water because it has more mass','Neither can be determined without conductivity testing','Solution A is salt water because its mass is exactly 50 g'],correct:0,solution:'Solution A: 50.0 g ÷ 50.0 mL = 1.00 g/mL, matching pure water\'s known density exactly. Solution B: 51.8 g ÷ 50.0 mL = 1.036 g/mL, denser than pure water, consistent with dissolved salt adding mass without adding much volume. This method works because density is an intensive property useful for identification.'},
{id:'p176',difficulty:'hard',type:'calc',tag:'Formula Counting',q:'How many total atoms are in 3 formula units of Ca(H2PO4)2?',answer:45,tolerance:1,solution:'One formula unit: Ca(1) + (H2PO4)2 = 4 H + 2 P + 8 O. Total = 1+4+2+8 = 15 atoms. For 3 formula units: 3 × 15 = <strong>45 atoms</strong>.'},

/* ── 3 short easy multi-step problems (fill the multi+easy filter gap) ── */
{id:'p177',difficulty:'easy',type:'multi',tag:'Multi-step',q:'A student compares two samples: Sample 1 is pure iron metal (Fe), which conducts electricity. Sample 2 is table salt (NaCl), used to season food. Which sample is an element?',choices:['Sample 1','Sample 2','Both','Neither'],correct:0,solution:'Sample 1 (iron) has only one type of atom — an element. Sample 2 (NaCl) has two different elements chemically bonded — a compound.'},
{id:'p178',difficulty:'easy',type:'multi',tag:'Multi-step',q:'A student observes two changes: (1) an ice cube melting on the counter, (2) a piece of wood burning in a fireplace. Which change is a chemical change?',choices:['Change 1','Change 2','Both','Neither'],correct:1,solution:'Melting (Change 1) is a physical change — the water is still H2O. Burning wood (Change 2) is a chemical change — new substances (CO2, H2O, ash) are formed.'},
{id:'p179',difficulty:'easy',type:'multi',tag:'Multi-step',q:'Jar A contains only unbonded Ne atoms. Jar B contains NaCl crystals, where each Na atom is bonded to a Cl atom in a fixed 1:1 ratio. Which jar holds a compound?',choices:['Jar A','Jar B','Both','Neither'],correct:1,solution:'Jar A has only one atom type, unbonded — an element. Jar B has two different atom types chemically bonded in a fixed ratio — the definition of a compound.'},

]; // end ALL_PROBLEMS — 179 problems total (86 original + 60 added + 30 hard expansion + 3 easy multi-step)
